        if excess < 1e-12 or not room:
            break
        den = sum(max(0.0, pref.get(a, 0.0)) for a in room)
        for a in room:
            w[a] += excess * (max(0.0, pref.get(a, 0.0)) / den if den > 0 else 1.0 / len(room))
