    smin, smax = min(valid_sc), max(valid_sc)
    span = (smax - smin) or 1e-9
    pref = {}
    for a in assets:
        sc = (float(score[a]) - smin) / span
        v = max(float(vols.get(a) or med_vol), 0.004)
        pref[a] = (0.55 + 1.35 * sc) / v
        if a in DEF and (bear or high_disp):
            pref[a] *= 1.6

